-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261104223000' and name='folder_look_prefs')=1 then '예' else '아니오' end as value
union all select 'photo tags color nullable smallint with 1 to 8 check, sort_order integer not null',case when exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_photo_tags') and attname='color' and not attisdropped and atttypid='int2'::regtype and not attnotnull) and exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_photo_tags') and attname='sort_order' and not attisdropped and atttypid='int4'::regtype and attnotnull) and (select count(*) from pg_constraint where conrelid=to_regclass('public.app_photo_tags') and conname='app_photo_tags_color_check' and contype='c' and convalidated)=1 then '예' else '아니오' end
union all select 'folder prefs: RLS on, one select policy, authenticated select only, none for anon',case when exists(select 1 from pg_class where oid=to_regclass('public.app_folder_prefs') and relrowsecurity) and (select count(*) from pg_policy where polrelid=to_regclass('public.app_folder_prefs') and polcmd='r')=1 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_folder_prefs'))=1 and has_table_privilege('authenticated','public.app_folder_prefs','select') and not has_table_privilege('authenticated','public.app_folder_prefs','insert,update,delete') and not has_any_column_privilege('anon','public.app_folder_prefs','select,insert,update,references') then '예' else '아니오' end
union all select 'apply functions: definer, empty search_path, no anon or PUBLIC execute',case when (select count(*) from pg_proc p where p.oid in(to_regprocedure('public.app_folder_prefs_apply(uuid,text,jsonb)'),to_regprocedure('public.app_photo_tag_look_apply(uuid,jsonb)')) and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'') !~ '(^|[{,])=')=2 then '예' else '아니오' end
union all select 'apply functions: authenticated only',case when has_function_privilege('authenticated','public.app_folder_prefs_apply(uuid,text,jsonb)','execute') and has_function_privilege('authenticated','public.app_photo_tag_look_apply(uuid,jsonb)','execute') and not has_function_privilege('service_role','public.app_folder_prefs_apply(uuid,text,jsonb)','execute') and not has_function_privilege('service_role','public.app_photo_tag_look_apply(uuid,jsonb)','execute') then '예' else '아니오' end
union all select 'photo tags: no color or order write privilege for authenticated, none for anon',case when not has_column_privilege('authenticated','public.app_photo_tags','color','insert,update') and not has_column_privilege('authenticated','public.app_photo_tags','sort_order','insert,update') and not has_any_column_privilege('anon','public.app_photo_tags','select,insert,update,references') then '예' else '아니오' end
union all select 'photo tags RLS on and no anon privilege',case when exists(select 1 from pg_class where oid=to_regclass('public.app_photo_tags') and relrowsecurity) and not has_any_column_privilege('anon','public.app_photo_tags','select,insert,update,references') then '예' else '아니오' end
union all select 'photo tags rows',(select count(*)::text from public.app_photo_tags)
union all select 'photo tags grants policies triggers hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_photo_tags')),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_photo_tags')),'')
  ||coalesce((select string_agg(t.tgname::text||':'||t.tgenabled::text||':'||t.tgfoid::regproc::text,',' order by t.tgname) from pg_trigger t where t.tgrelid=to_regclass('public.app_photo_tags') and not t.tgisinternal),''));
